    "objetivoPrincipal": "Interiorizar los conceptos tácticos avanzados de geometría del juego, equilibrio de líneas y ocupación racional, mejorando la interpretación del juego y la toma de decisiones colectiva.",
    "objetivoTecnico": "Pases con peso y dirección precisa, controles orientados en función del espacio y velocidad de circulación colectiva.",
